style.css:
@-moz-document domain("youtube.com") {
/* Fondo general */
    body, #content {
        background-color: #000000 !important;
        color: #ff79c6 !important;
    }

    /* Barra de navegación */
    #container, #masthead-container {
        background-color: #121212 !important;
        border-bottom: 2px solid #ff00ff !important;
    }

    /* Texto */
    a, yt-formatted-string {
        color: #ff79c6 !important;
    }

    /* Botones y enlaces */
    .ytd-button-renderer, .yt-simple-endpoint {
        background-color: #282828 !important;
        border: 1px solid #ff00ff !important;
        color: #ff79c6 !important;
    }
    .ytd-button-renderer:hover, .yt-simple-endpoint:hover {
        background-color: #ff00ff !important;
        color: #000000 !important;
    }

    /* Fondos de los videos */
    #primary, ytd-rich-item-renderer {
        background-color: #121212 !important;
    }

    /* Barra lateral */
    #guide, #guide-inner-content {
        background-color: #1e1e1e !important;
        color: #ff79c6 !important;
    }

    /* Reproductor de video */
    .html5-video-player {
        background-color: #000000 !important;
    }

    /* Iconos */
    tp-yt-iron-icon {
        color: #ff00ff !important;
    }

    /* Barras de progreso */
    .ytp-progress-bar-container {
        background-color: #282828 !important;
    }
    .ytp-scrubber-button, .ytp-play-progress {
        background-color: #ff00ff !important;
    }
}
